# Always validate coordinate bounds and action safety
def validate_gui_action(action_type, coordinate, blocked_zones):
    x, y = coordinate
    for zone in blocked_zones:
        # E.g. block taskbar, shutdown button, or private keys area
        if zone['x1'] <= x <= zone['x2'] and zone['y1'] <= y <= zone['y2']:
            raise SecurityException(f"Attempted click in protected OS region: ({x}, {y})")
    return True

